window.AUTH=window.AUTH||{};window.AUTH["22-448"]={"d":"22-448","id":"2023/22-448","n":"Consumer Financial Protection Bureau v. Community Financial Services Association of America","briefs":[{"k":"petitioner","label":"Brief of petitioners Consumer Financial Protection Bureau, et al.","date":"2023-05-08","url":"https://www.supremecourt.gov/DocketPDF/22/22-448/266373/20230508190055738_22-448tsUnitedStates.pdf","side":"pet","n":121},{"k":"respondent","label":"Brief of respondents Community Financial Services Association of America, Limited, et al.","date":"2023-07-03","url":"https://www.supremecourt.gov/DocketPDF/22/22-448/270281/20230703105533891_22-448%20CFSA%20Brief%20for%20Respondents.pdf","side":"res","n":57},{"k":"reply","label":"Reply of petitioners Consumer Financial Protection Bureau, et al.","date":"2023-08-02","url":"https://www.supremecourt.gov/DocketPDF/22/22-448/274470/20230802113142512_22-448rbUnitedStates.pdf","side":"pet","n":46}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/601us2r21_7648.pdf","tr":true,"items":[{"t":"case","label":"Armstrong v. Exceptional Child Ctr., Inc.","cite":"575 U.S. 320","y":2015,"id":"2014/14-15","sc":1,"by":{"0":"44"}},{"t":"case","label":"Barr v. American Ass’n of Political Consultants, Inc.","cite":"140 S. Ct. 2335","y":2020,"id":"2019/19-631","sc":1,"by":{"0":"39, 41"}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"by":{"0":"46"}},{"t":"case","label":"CFPB v. All Am. Check Cashing, Inc.","cite":"33 F.4th 218","y":2022,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/33/218/","by":{"0":"28","1":"13, 41–42","2":"20"},"q":[{"src":"brief","b":1,"text":"the CFPB Director need only send a perfunctory letter to the Fed[.]","cite":"33 F.4th at 223"},{"src":"brief","b":1,"text":"to bind its own hands in the future when political winds change.","cite":"33 F.4th at 239"},{"src":"brief","b":2,"text":"[a] valid appropriation ‘is as much a precondition to every exercise of executive authority . . . as a constitutionally proper appointment or delegation of authority.’","cite":"33 F.4th 218, 242"}]},{"t":"case","label":"CFPB v. Law Offices of Crystal Moroney, P.C.","cite":"63 F.4th 174","y":2023,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/63/174/","by":{"0":"14, 25, 28, 33","2":"8, 10, 12"},"q":[{"src":"brief","b":0,"text":"the absence of any restrictions in the Appropriations Clause other than that Congress must authorize government funding in a prior statute.","cite":"63 F.4th at 182"},{"src":"brief","b":0,"text":"be drawn from a particular ‘source.’","cite":"63 F.4th at 182"},{"src":"brief","b":2,"text":"the CFPB’s funding structure is proper under the nondelegation doctrine.","cite":"63 F.4th 174, 184"}]},{"t":"case","label":"Chiafalo v. Washington","cite":"140 S. Ct. 2316","y":2020,"id":"2019/19-465","sc":1,"by":{"0":"18"},"q":[{"src":"brief","b":0,"text":"‘Long settled and established practice’ may have ‘great weight in a proper interpretation of constitutional provisions.’","cite":"140 S. Ct. 2316, 2326"}]},{"t":"case","label":"Cincinnati Soap Co. v. United States","cite":"301 U.S. 308","y":1937,"id":"scdb/1936-117","sc":1,"by":{"0":"8, 11, 14, 19, 24","2":"8, 10"},"q":[{"src":"brief","b":0,"text":"the Appropriations Clause expressly ‘was intended as a restriction upon the disbursing authority of the Executive department,’","cite":"301 U.S. 308, 321"},{"src":"brief","b":0,"text":"means simply that no money can be paid out of the Treasury unless it has been appropriated by an act of Congress.","cite":"301 U.S. 308, 321"},{"src":"brief","b":2,"text":"[A]cts of Congress are replete with instances of general appropriations of large amounts, to be allotted and expended as directed by designated government agencies.","cite":"301 U.S. 308, 322"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"no money can be paid out of the Treasury unless it has been appropriated by an act of Congress.","cite":"301 U. S. 308, 321"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"expended as directed by designated government agencies.","cite":"301 U. S. 308, 322"},{"src":"argument","who":"Justice Jackson","text":"-- in Cincinnati Soap, I -- I had understood the point of the Appropriations Clause to prevent the executive in other circumstances from exercising the authority to take money without consent of the legislature."}]},{"t":"case","label":"Clinton v. City of New York","cite":"524 U.S. 417","y":1998,"id":"1997/97-1374","sc":1,"by":{"0":"19","1":"20, 27, 32","2":"6, 7, 9, 10"},"q":[{"src":"brief","b":0,"text":"From 1789-1791, the First Congress made lump-sum appropriations for the entire Government—‘sums not exceeding’ specified amounts for broad purposes.","cite":"524 U.S. 417, 466"},{"src":"brief","b":0,"text":"[e]xamples of appropriations committed to the discretion of the President abound in our history.","cite":"524 U.S. at 467"},{"src":"brief","b":1,"text":"one Congress cannot yield up its own powers, much less those of other Congresses to follow,","cite":"524 U.S. at 452"},{"src":"brief","b":2,"text":"le[ft] the decision whether to spend the money to the President’s unfettered discretion.","cite":"524 U.S. 417, 466"},{"src":"brief","b":2,"text":"‘sum[s] not exceeding’ specified amounts for broad purposes.","cite":"524 U.S. at 466"},{"src":"argument","who":"General Prelogar","text":"And as Justice Scalia emphasized in his concurring opinion in Clinton versus City of New York, if you look across the course of history from 1789 on, it has been, in the appropriations context, marked by very broad delegations of authority to the executive branch to spend within the bounds set by Congress."},{"src":"argument","who":"Justice Kagan","text":"And, you know, Justice Scalia, in Clinton, said the constitutionality of such appropriations has never seriously been questioned. So, if that's really the core --"}]},{"t":"case","label":"Collins v. Yellen","cite":"141 S. Ct. 1761","y":2021,"id":"2020/19-422","sc":1,"by":{"0":"9, 35, 39, 43","1":"7–8, 39, 46–47, 51","2":"14, 15"},"q":[{"src":"argument","who":"General Prelogar","text":"Nor is there any principled line here that the Court could apply to try to ascertain and weigh the relative difference of function between different agencies, as the Court observed in -- in Collins versus Yellen most recently."}]},{"t":"case","label":"Community Fin. Servs. Ass’n of Am., Ltd. v. CFPB","cite":"143 S. Ct. 981","y":2023,"url":"https://www.courtlistener.com/c/S.%20Ct./143/981/","sc":1,"by":{"0":"7"}},{"t":"case","label":"Free Enter. Fund v. Public Co. Accounting Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"by":{"0":"33, 39, 45","1":"17, 24, 27, 44","2":"16, 17"},"q":[{"src":"brief","b":1,"text":"the separation of powers does not depend … on whether ‘the encroached-upon branch approves the encroachment.’","cite":"561 U.S. at 497"}]},{"t":"case","label":"Harlow v. Fitzgerald","cite":"457 U.S. 800","y":1982,"id":"1981/80-945","sc":1,"by":{"0":"46"}},{"t":"case","label":"Harrington v. Bush","cite":"553 F.2d 190","y":1977,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/553/190/","by":{"0":"24"}},{"t":"case","label":"Hudson v. Michigan","cite":"547 U.S. 586","y":2006,"id":"2005/04-1360","sc":1,"by":{"0":"46"}},{"t":"case","label":"Knote v. United States","cite":"95 U.S. 149","y":1877,"id":"scdb/1877-053","sc":1,"by":{"0":"15"}},{"t":"case","label":"Lebron v. National R.R. Passenger Corp.","cite":"513 U.S. 374","y":1995,"id":"1994/93-1525","sc":1,"by":{"0":"37","1":"30"}},{"t":"case","label":"Lincoln v. Vigil","cite":"508 U.S. 182","y":1993,"id":"1992/91-1833","sc":1,"by":{"0":"19, 26"},"q":[{"src":"brief","b":0,"text":"the very point of a lump-sum appropriation is to give an agency the capacity to adapt to changing circumstances and meet its statutory responsibilities in what it sees as the most effective or desirable way.","cite":"508 U.S. 182, 192"},{"src":"brief","b":0,"text":"the very point of a lump-sum appropriation.","cite":"508 U.S. at 192"}]},{"t":"case","label":"Maine Cmty. Health Options v. United States","cite":"140 S. Ct. 1308","y":2020,"id":"2019/18-1023","sc":1,"by":{"0":"16"},"q":[{"src":"brief","b":0,"text":"federal employees and officers [from] mak[ing] or authoriz[ing] payments without appropriations.","cite":"140 S. Ct. 1308, 1321"}]},{"t":"case","label":"NLRB v. Noel Canning","cite":"573 U.S. 513","y":2014,"id":"2013/12-1281","sc":1,"by":{"0":"18","1":"36","2":"18"},"q":[{"src":"brief","b":0,"text":"look[s] to the actual practice of Government","cite":"573 U.S. 513, 557"},{"src":"brief","b":2,"text":"‘long settled and established practice is a consideration of great weight in the proper interpretation of constitutional provisions’ regulating the relationship between Congress and the President.","cite":"573 U.S. 513, 524"}]},{"t":"case","label":"Norton v. Shelby Cnty.","cite":"118 U.S. 425","y":1886,"id":"scdb/1885-275","sc":1,"by":{"0":"46"},"q":[{"src":"brief","b":0,"text":"the good order and peace of society.","cite":"118 U.S. 425, 441"}]},{"t":"case","label":"OPM v. Richmond","cite":"496 U.S. 414","y":1990,"id":"1989/88-1943","sc":1,"by":{"0":"7, 14, 38","1":"11, 13, 15, 18, 26–27, 33, 41–42, 45","2":"14, 16"},"q":[{"src":"brief","b":0,"text":"[t]he Appropriations Clause ‘means simply that no money can be paid out of the Treasury unless it has been appropriated by an act of Congress.’","cite":"496 U.S. 414, 424"},{"src":"brief","b":0,"text":"the payment of money from the Treasury must be authorized by a statute.","cite":"496 U.S. at 424"},{"src":"brief","b":1,"text":"all the taxes raised from the people[] as well as revenues arising from other sources.","cite":"496 U.S. 414, 427"},{"src":"brief","b":1,"text":"to secure regularity, punctuality, and fidelity[] in the disbursements of the public money.","cite":"496 U.S. at 427"},{"src":"brief","b":2,"text":"is to assure that public funds will be spent according to the letter of the difficult judgments reached by Congress,","cite":"496 U.S. at 428"},{"src":"argument","who":"General Prelogar","text":"Of course, at the time of the founding, ratification, the Treasury Department hadn't even been created, and that's also how this Court has described the scope of the Appropriations Clause in cases like OPM versus Richmond, where it referred to public monies generally."}]},{"t":"case","label":"PHH Corp. v. CFPB","cite":"881 F.3d 75","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/881/75/","by":{"0":"25","1":"5, 38, 40"},"q":[{"src":"brief","b":1,"text":"the agencies that previously administered the CFPB’s statutes, in part because those agencies depended on industry fees.","cite":"881 F.3d 75, 95"},{"src":"brief","b":1,"text":"historical anomaly … due to [its] special functions.","cite":"881 F.3d 75, 192 n.17"}]},{"t":"case","label":"Seila Law LLC v. CFPB","cite":"140 S. Ct. 2183","y":2020,"id":"2019/19-7","sc":1,"by":{"0":"6, 12, 14, 36, 39, 40, 41","1":"1–4, 22–23, 34, 38–39, 43–45","2":"3"},"q":[{"src":"brief","b":0,"text":"sever[] any problematic portions while leaving the remainder intact.","cite":"140 S. Ct. 2183, 2209"},{"src":"brief","b":0,"text":"severing any problematic portions while leaving the remainder intact.","cite":"140 S. Ct. at 2209"},{"src":"brief","b":1,"text":"may unilaterally, without meaningful supervision, issue final regulations, oversee adjudications, set enforcement priorities, initiate prosecutions, and determine what penalties to impose on private parties.","cite":"140 S. Ct. 2183, 2203-04"},{"src":"brief","b":1,"text":"Perhaps the most telling indication of a severe constitutional problem with an executive entity is a lack of historical precedent to support it.","cite":"140 S. Ct. at 2201"},{"src":"brief","b":2,"text":"provide[] contemporaneous and weighty evidence of the Constitution’s meaning.","cite":"140 S. Ct. 2183, 2197"},{"src":"argument","who":"General Prelogar","text":"It repeated it in Seila Law. But that history works both ways. The Court has likewise said that the fact that a way of structuring government is well rooted in history and traces back to the founding is powerful evidence of the contemporaneous understanding of original intent, and that's the box we're in here."},{"src":"argument","who":"General Prelogar","text":"This Court emphasized that point in Seila Law. And, here, the Fifth Circuit didn't even stop to consider whether any aspect of the CFPB's funding mechanism could be severed or would provide a basis to therefore limit the damage to Congress's work in trying to get this agency funded."},{"src":"argument","who":"Justice Kavanaugh","text":"-- in the single director who was protected by for-cause removal, but that, of course, was fixed and addressed in Seila Law. And now it's not independent at all, at least as the term \"independent\" is used."}]},{"t":"case","label":"Seminole Tribe of Fla. v. Florida","cite":"517 U.S. 44","y":1996,"id":"1995/94-12","sc":1,"by":{"0":"44"},"q":[{"src":"brief","b":0,"text":"hesitate before casting aside those limitations","cite":"517 U.S. 44, 74"}]},{"t":"case","label":"United Biscuit Co. of Am. v. Wirtz","cite":"359 F.2d 206","y":1965,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/359/206/","by":{"0":"25"},"q":[{"src":"brief","b":0,"text":"to distinguish those acts of Congress which created valid appropriations from those which did not.","cite":"359 F.2d 206, 213 n.14"}]},{"t":"case","label":"United States v. Arthrex","cite":"141 S. Ct. 1970","y":2021,"id":"2020/19-1434","sc":1,"by":{"0":"40","1":"18, 33, 43–45"},"q":[{"src":"brief","b":0,"text":"give[s] ‘full effect’ to the Constitution and to whatever portions of the statute are ‘not repugnant’ to the Constitution, effectively severing the unconstitutional portion of the statute.","cite":"141 S. Ct. 1970, 1986"},{"src":"brief","b":1,"text":"the public … [to] wonder on whom the blame or the punishment … ought really to fall.","cite":"141 S. Ct. 1970, 1982"}]},{"t":"case","label":"United States v. Morrison","cite":"449 U.S. 361","y":1981,"id":"1980/79-395","sc":1,"by":{"0":"45","2":"24"},"q":[{"src":"brief","b":0,"text":"not unnecessarily infringe on competing interests,","cite":"449 U.S. 361, 364"},{"src":"brief","b":2,"text":"unnecessarily infringe on [those] competing interests","cite":"449 U.S. 361, 364"}]},{"t":"case","label":"United States v. Vaello Madero","cite":"142 S. Ct. 1539","y":2022,"id":"2021/20-303","sc":1,"by":{"0":"14"}},{"t":"case","label":"United States Dep’t of the Navy v. Federal Labor Relations Auth.","cite":"665 F.3d 1339","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/665/1339/","by":{"0":"14, 24, 38","1":"1, 12, 15"},"q":[{"src":"brief","b":0,"text":"protects Congress’s ‘exclusive power over the federal purse.’","cite":"665 F.3d 1339, 1346"},{"src":"brief","b":1,"text":"one of the most important authorities allocated to Congress in the Constitution’s necessary partition of power among the several departments.","cite":"665 F.3d 1339, 1346"},{"src":"brief","b":1,"text":"particularly important as a restraint on Executive Branch officers,","cite":"665 F.3d at 1347"}]},{"t":"case","label":"Waite v. Santa Cruz","cite":"184 U.S. 302","y":1902,"id":"scdb/1901-108","sc":1,"by":{"0":"46"}},{"t":"case","label":"Winter v. Natural Res. Def. Council, Inc.","cite":"555 U.S. 7","y":2008,"id":"2008/07-1239","sc":1,"by":{"0":"45"}},{"t":"law","label":"Pub. L. No. 91-206","url":"https://www.govinfo.gov/link/statute/84/49","by":{"0":"23"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"0":"44"}},{"t":"usc","label":"5 U.S.C. § 702","url":"https://www.law.cornell.edu/uscode/text/5/702","by":{"0":"44"},"q":[{"src":"brief","b":0,"text":"deny relief on any other appropriate legal or equitable ground.","cite":"5 U.S.C. 702"}]},{"t":"usc","label":"31 U.S.C. § 1341","url":"https://www.law.cornell.edu/uscode/text/31/1341","by":{"0":"43"}},{"t":"usc","label":"31 U.S.C. § 1349","url":"https://www.law.cornell.edu/uscode/text/31/1349","subs":["(a)"],"by":{"0":"44"}},{"t":"usc","label":"31 U.S.C. § 1350","url":"https://www.law.cornell.edu/uscode/text/31/1350","by":{"0":"44"}},{"t":"usc","label":"12 U.S.C. § 1811","url":"https://www.law.cornell.edu/uscode/text/12/1811","by":{"0":"23"}},{"t":"usc","label":"12 U.S.C. § 1815","url":"https://www.law.cornell.edu/uscode/text/12/1815","subs":["(d)"],"by":{"0":"23"}},{"t":"usc","label":"12 U.S.C. § 1818","url":"https://www.law.cornell.edu/uscode/text/12/1818","subs":["(a)(1)"],"by":{"0":"36, 34"},"q":[{"src":"argument","who":"General Prelogar","text":"Section 1818 to demonstrate that these functions are not different. Nor is there any principled line here that the Court could apply to try to ascertain and weigh the relative difference of function between different agencies, as the Court observed in -- in Collins versus Yellen most recently."}]},{"t":"usc","label":"12 U.S.C. § 1820","url":"https://www.law.cornell.edu/uscode/text/12/1820","subs":["(e)"],"by":{"0":"23"}},{"t":"usc","label":"12 U.S.C. § 1828","url":"https://www.law.cornell.edu/uscode/text/12/1828","by":{"0":"36"}},{"t":"law","label":"Pub. L. No. 117-103","url":"https://www.govinfo.gov/link/plaw/117/public/103","by":{"0":"26","1":"35","2":"7"}},{"t":"usc","label":"12 U.S.C. § 5301","url":"https://www.law.cornell.edu/uscode/text/12/5301","by":{"0":"2"}},{"t":"usc","label":"12 U.S.C. § 5302","url":"https://www.law.cornell.edu/uscode/text/12/5302","by":{"0":"12, 40, 41","2":"20"}},{"t":"usc","label":"12 U.S.C. § 5491","url":"https://www.law.cornell.edu/uscode/text/12/5491","subs":["(a)"],"stext":{"head":"§5491. Establishment of the Bureau of Consumer Financial Protection","paras":[[0,"(a) Bureau established"],[0,"There is established in the Federal Reserve System, an independent bureau to be known as the \"Bureau of Consumer Financial Protection\", which shall regulate the offering and provision of consumer financial products or services under the Federal consumer financial laws. The Bureau shall be considered an Executive agency, as defined in section 105 of title 5. Except as otherwise provided expressly by law, all Federal laws dealing with public or Federal contracts, property, works, officers, employees, budgets, or funds, including the provisions of chapters 5 and 7 of title 5, shall apply to the exercise of the powers of the Bureau."],[0,"(b) Director and Deputy Director"],[0,"(1) In general"],[1,"There is established the position of the Director, who shall serve as the head of the Bureau."],[0,"(2) Appointment"],[1,"Subject to paragraph (3), the Director shall be appointed by the President, by and with the advice and consent of the Senate."],[0,"(3) Qualification"],[1,"The President shall nominate the Director from among individuals who are citizens of the United States."],[0,"(4) Compensation"],[1,"The Director shall be compensated at the rate prescribed for level II of the Executive Schedule under section 5313 of title 5."],[0,"(5) Deputy Director"],[1,"There is established the position of Deputy Director, who shall—"],[2,"(A) be appointed by the Director; and"],[2,"(B) serve as acting Director in the absence or unavailability of the Director."],[0,"(c) Term"],[0,"(1) In general"],[1,"The Director shall serve for a term of 5 years."],[0,"(2) Expiration of term"],[1,"An individual may serve as Director after the expiration of the term for which appointed, until a successor has been appointed and qualified."],[0,"(3) Removal for cause"],[1,"The President may remove the Director for inefficiency, neglect of duty, or malfeasance in office."],[0,"(d) Service restriction"],[0,"No Director or Deputy Director may hold any office, position, or employment in any Federal reserve bank, Federal home loan bank, covered person, or service provider during the period of service of such person as Director or Deputy Director."],[0,"(e) Offices"],[0,"The principal office of the Bureau shall be in the District of Columbia. The Director may establish regional offices of the Bureau, including in cities in which the Federal reserve banks, or branches of such banks, are located, in order to carry out the responsibilities assigned to the Bureau under the Federal consumer financial laws."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/5491?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 33","1":"4","2":"15"},"q":[{"src":"brief","b":1,"text":"inefficiency, neglect of duty, or malfeasance in office.","cite":"12 U.S.C. § 5491(b)(1)"}]},{"t":"usc","label":"12 U.S.C. § 5496","url":"https://www.law.cornell.edu/uscode/text/12/5496","subs":["(a)","(b)","(c)(2)"],"by":{"0":"4, 37, 37, 4, 37"},"q":[{"src":"brief","b":0,"text":"budget request of the previous year.","cite":"12 U.S.C. 5496(c)(2)"}]},{"t":"usc","label":"12 U.S.C. § 5497","url":"https://www.law.cornell.edu/uscode/text/12/5497","subs":["(a)","(a)(1)","(a)(2)","(a)(2)(A)","(a)(2)(A)(iii)","(a)(2)(B)","(a)(2)(C)","(a)(5)","(b)(1)","(b)(2)","(c)(1)","(c)(2)","(d)","(b)(3)"],"stext":{"head":"§5497. Funding; penalties and fines","paras":[[0,"(a) Transfer of funds from Board Of Governors"],[0,"(1) In general"],[1,"Each year (or quarter of such year), beginning on the designated transfer date, and each quarter thereafter, the Board of Governors shall transfer to the Bureau from the combined earnings of the Federal Reserve System, the amount determined by the Director to be reasonably necessary to carry out the authorities of the Bureau under Federal consumer financial law, taking into account such other sums made available to the Bureau from the preceding year (or quarter of such year)."],[0,"(2) Funding cap"],[0,"(A) In general"],[2,"Notwithstanding paragraph (1), and in accordance with this paragraph, the amount that shall be transferred to the Bureau in each fiscal year shall not exceed a fixed percentage of the total operating expenses of the Federal Reserve System, as reported in the Annual Report, 2009, of the Board of Governors, equal to—"],[3,"(i) 10 percent of such expenses in fiscal year 2011;"],[3,"(ii) 11 percent of such expenses in fiscal year 2012; and"],[3,"(iii) 12 percent of such expenses in fiscal year 2013, and in each year thereafter."],[0,"(B) Adjustment of amount"],[2,"The dollar amount referred to in subparagraph (A)(iii) shall be adjusted annually, using the percent increase, if any, in the employment cost index for total compensation for State and local government workers published by the Federal Government, or the successor index thereto, for the 12-month period ending on September 30 of the year preceding the transfer."],[0,"(C) Reviewability"],[2,"Notwithstanding any other provision in this title,1 the funds derived from the Federal Reserve System pursuant to this subsection shall not be subject to review by the Committees on Appropriations of the House of Representatives and the Senate."],[0,"(3) Transition period"],[1,"Beginning on July 21, 2010, and until the designated transfer date, the Board of Governors shall transfer to the Bureau the amount estimated by the Secretary needed to carry out the authorities granted to the Bureau under Federal consumer financial law, from July 21, 2010 until the designated transfer date."],[0,"(4) Budget and financial management"],[0,"(A) Financial operating plans and forecasts"],[2,"The Director shall provide to the Director of the Office of Management and Budget copies of the financial operating plans and forecasts of the Director, as prepared by the Director in the ordinary course of the operations of the Bureau, and copies of the quarterly reports of the financial condition and results of operations of the Bureau, as prepared by the Director in the ordinary course of the operations of the Bureau."],[0,"(B) Financial statements"],[2,"The Bureau shall prepare annually a statement of—"],[3,"(i) assets and liabilities and surplus or deficit;"],[3,"(ii) income and expenses; and"],[3,"(iii) sources and application of funds."],[0,"(C) Financial management systems"],[2,"The Bureau shall implement and maintain financial management systems that comply substantially with Federal financial management systems requirements and applicable Federal accounting standards."],[0,"(D) Assertion of internal controls"],[2,"The Director shall provide to the Comptroller General of the United States an assertion as to the effectiveness of the internal controls that apply to financial reporting by the Bureau, using the standards established in section 3512(c) of title 31."],[0,"(E) Rule of construction"],[2,"This subsection may not be construed as implying any obligation on the part of the Director to consult with or obtain the consent or approval of the Director of the Office of Management and Budget with respect to any report, plan, forecast, or other information referred to in subparagraph (A) or any jurisdiction or oversight over the affairs or operations of the Bureau."],[0,"(F) Financial statements"],[2,"The financial statements of the Bureau shall not be consolidated with the financial statements of either the Board of Governors or the Federal Reserve System."],[0,"(5) Audit of the Bureau"],[0,"(A) In general"],[2,"The Comptroller General shall annually audit the financial transactions of the Bureau in accordance with the United States generally accepted government auditing standards, as may be prescribed by the Comptroller General of the United States. The audit shall be conducted at the place or places where accounts of the Bureau are normally kept. The representatives of the Government Accountability Office shall have access to the personnel and to all books, accounts, documents, papers, records (including electronic records), reports, files, and all other papers, automated data, things, or property belonging to or under the control of or used or employed by the Bureau pertaining to its financial transactions and necessary to facilitate the audit, and such representatives shall be afforded full facilities for verifying transactions with the balances or securities held by depositories, fiscal agents, and custodians. All such books, accounts, documents, records, reports, files, papers, and property of the Bureau shall remain in possession and custody of the Bureau. The Comptroller General may obtain and duplicate any such books, accounts, documents, records, working papers, automated data and files, or other information relevant to such audit without cost to the Comptroller General, and the right of access of the Comptroller General to such information shall be enforceable pursuant to section 716(c) of title 31."],[0,"(B) Report"],[2,"The Comptroller General shall submit to the Congress a report of each annual audit conducted under this subsection. The report to the Congress shall set forth the scope of the audit and shall include the statement of assets and liabilities and surplus or deficit, the statement of income and expenses, the statement of sources and application of funds, and such comments and information as may be deemed necessary to inform Congress of the financial operations and condition of the Bureau, together with such recommendations with respect thereto as the Comptroller General may deem advisable. A copy of each report shall be furnished to the President and to the Bureau at the time submitted to the Congress."],[0,"(C) Assistance and costs"],[2,"For the purpose of conducting an audit under this subsection, the Comptroller General may, in the discretion of the Comptroller General, employ by contract, without regard to section 6101 of title 41, professional services of firms and organizations of certified public accountants for temporary periods or for special purposes. Upon the request of the Comptroller General, the Director of the Bureau shall transfer to the Government Accountability Office from funds available, the amount requested by the Comptroller General to cover the full costs of any audit and report conducted by the Comptroller General. The Comptroller General shall credit funds transferred to the account established for salaries and expenses of the Government Accountability Office, and such amount shall be available upon receipt and without fiscal year limitation to cover the full costs of the audit and report."],[0,"(b) Consumer Financial Protection Fund"],[0,"(1) Separate fund in Federal Reserve established"],[1,"There is established in the Federal Reserve a separate fund, to be known as the \"Bureau of Consumer Financial Protection Fund\" (referred to in this section as the \"Bureau Fund\"). The Bureau Fund shall be maintained and established at a Federal reserve bank, in accordance with such requirements as the Board of Governors may impose."],[0,"(2) Fund receipts"],[1,"All amounts transferred to the Bureau under subsection (a) shall be deposited into the Bureau Fund."],[0,"(3) Investment authority"],[0,"(A) Amounts in Bureau Fund may be invested"],[2,"The Bureau may request the Board of Governors to direct the investment of the portion of the Bureau Fund that is not, in the judgment of the Bureau, required to meet the current needs of the Bureau."],[0,"(B) Eligible investments"],[2,"Investments authorized by this paragraph shall be made in obligations of the United States or obligations that are guaranteed as to principal and interest by the United States, with maturities suitable to the needs of the Bureau Fund, as determined by the Bureau."],[0,"(C) Interest and proceeds credited"],[2,"The interest on, and the proceeds from the sale or redemption of, any obligations held in the Bureau Fund shall be credited to the Bureau Fund."],[0,"(c) Use of funds"],[0,"(1) In general"],[1,"Funds obtained by, transferred to, or credited to the Bureau Fund shall be immediately available to the Bureau and under the control of the Director, and shall remain available until expended, to pay the expenses of the Bureau in carrying out its duties and responsibilities. The compensation of the Director and other employees of the Bureau and all other expenses thereof may be paid from, obtained by, transferred to, or credited to the Bureau Fund under this section."],[0,"(2) Funds that are not Government funds"],[1,"Funds obtained by or transferred to the Bureau Fund shall not be construed to be Government funds or appropriated monies."],[0,"(3) Amounts not subject to apportionment"],[1,"Notwithstanding any other provision of law, amounts in the Bureau Fund and in the Civil Penalty Fund established under subsection (d) shall not be subject to apportionment for purposes of chapter 15 of title 31 or under any other authority."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/5497?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3","1":"1–2, 5–6, 16, 18–19, 22, 25, 29, 32, 44–45","2":"9, 10, 19, 20, 8-10, 15, 20, 6, 6, 8, 8, 10, 20"},"q":[{"src":"brief","b":0,"text":"from the combined earnings of the Federal Reserve System.","cite":"12 U.S.C. 5497(a)(1)"},{"src":"brief","b":0,"text":"shall remain available until expended, to pay the expenses of the Bureau in carrying out its duties and responsibilities.","cite":"12 U.S.C. 5497(c)(1)"},{"src":"brief","b":1,"text":"amount determined by the Director to be reasonably necessary to carry out the authorities of the Bureau.","cite":"12 U.S.C. § 5497(a)(1)"},{"src":"brief","b":1,"text":"not, in the judgment of the Bureau, required to meet [its] current needs.","cite":"12 U.S.C. § 5497(b)(3)"},{"src":"brief","b":2,"text":"reasonably necessary to carry out [its] authorities.","cite":"12 U.S.C. 5497(a)(1)"},{"src":"brief","b":2,"text":"taking into account such other sums made available to the Bureau from the preceding year.","cite":"12 U.S.C. 5497(a)(1)"},{"src":"opinion","who":"Justice Jackson, concurring","text":"the combined earnings of the Federal Reserve System,","cite":"12 U. S. C. § 5497(a)(1)"}]},{"t":"usc","label":"12 U.S.C. § 5511","url":"https://www.law.cornell.edu/uscode/text/12/5511","subs":["(a)","(b)","(c)"],"by":{"0":"3","2":"10, 10"}},{"t":"usc","label":"12 U.S.C. § 5512","url":"https://www.law.cornell.edu/uscode/text/12/5512","subs":["(b)(1)"],"by":{"0":"3"}},{"t":"usc","label":"12 U.S.C. § 5531","url":"https://www.law.cornell.edu/uscode/text/12/5531","subs":["(b)"],"by":{"0":"3, 5"},"q":[{"src":"brief","b":0,"text":"unfair, deceptive, or abusive acts or practices in connection with any transaction with a consumer for a consumer financial product or service.","cite":"12 U.S.C. 5531(b)"}]},{"t":"usc","label":"12 U.S.C. § 5581","url":"https://www.law.cornell.edu/uscode/text/12/5581","subs":["(b)(1)","(b)(2)","(b)(4)","(b)(6)"],"by":{"0":"2, 36, 36, 36, 36"}},{"t":"usc","label":"15 U.S.C. § 1693","url":"https://www.law.cornell.edu/uscode/text/15/1693","by":{"0":"47"}},{"t":"usc","label":"15 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/15/1681","by":{"0":"47"}},{"t":"usc","label":"15 U.S.C. § 1692","url":"https://www.law.cornell.edu/uscode/text/15/1692","by":{"0":"47"}},{"t":"usc","label":"12 U.S.C. § 1131","url":"https://www.law.cornell.edu/uscode/text/12/1131","by":{"0":"23"}},{"t":"usc","label":"12 U.S.C. § 2250","url":"https://www.law.cornell.edu/uscode/text/12/2250","subs":["(b)(2)"],"by":{"0":"23, 32, 37"}},{"t":"usc","label":"12 U.S.C. § 1751","url":"https://www.law.cornell.edu/uscode/text/12/1751","by":{"0":"23"}},{"t":"usc","label":"12 U.S.C. § 1755","url":"https://www.law.cornell.edu/uscode/text/12/1755","subs":["(a)","(b)"],"by":{"0":"23, 23"}},{"t":"usc","label":"12 U.S.C. § 221","url":"https://www.law.cornell.edu/uscode/text/12/221","by":{"0":"23"}},{"t":"usc","label":"12 U.S.C. § 222","url":"https://www.law.cornell.edu/uscode/text/12/222","by":{"0":"34","1":"37"}},{"t":"usc","label":"12 U.S.C. § 243","url":"https://www.law.cornell.edu/uscode/text/12/243","stext":{"head":"§243. Assessments upon Federal reserve banks to pay expenses","paras":[[0,"The Board of Governors of the Federal Reserve System shall have power to levy semiannually upon the Federal reserve banks, in proportion to their capital stock and surplus, an assessment sufficient to pay its estimated expenses and the salaries of its members and employees for the half year succeeding the levying of such assessment, together with any deficit carried forward from the preceding half year, and such assessments may include amounts sufficient to provide for the acquisition by the Board in its own name of such site or building in the District of Columbia as in its judgment alone shall be necessary for the purpose of providing suitable and adequate quarters for the performance of its functions. After September 1, 2000, the Board may also use such assessments to acquire, in its own name, a site or building (in addition to the facilities existing on such date) to provide for the performance of the functions of the Board. After approving such plans, estimates, and specifications as it shall have caused to be prepared, the Board may, notwithstanding any other provision of law, cause to be constructed on any site so acquired by it a building or buildings suitable and adequate in its judgment for its purposes and proceed to take all such steps as it may deem necessary or appropriate in connection with the construction, equipment, and furnishing of such building or buildings. The Board may maintain, enlarge, or remodel any building or buildings so acquired or constructed and shall have sole control of such building or buildings and space therein."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/243?type=usc&year=mostrecent&link-type=html"},"by":{"0":"22, 23, 26, 30, 33","1":"37","2":"3, 18"},"q":[{"src":"brief","b":0,"text":"assessment[s] sufficient to pay its estimated expenses and the salaries of its members and employees.","cite":"12 U.S.C. 243"},{"src":"brief","b":2,"text":"sufficient to pay its estimated expenses,","cite":"12 U.S.C. 243"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"suffcient to pay its estimated expenses.","cite":"12 U. S. C. § 243"}]},{"t":"usc","label":"12 U.S.C. § 244","url":"https://www.law.cornell.edu/uscode/text/12/244","by":{"0":"22, 23, 37"}},{"t":"usc","label":"12 U.S.C. § 248","url":"https://www.law.cornell.edu/uscode/text/12/248","stext":{"head":"§248. Enumerated powers","paras":[[0,"The Board of Governors of the Federal Reserve System shall be authorized and empowered:"],[0,"(a) Examination of accounts and affairs of banks; publication of weekly statements; reports of liabilities and assets of depository institutions; covered institutions"],[0,"(1) To examine at its discretion the accounts, books, and affairs of each Federal reserve bank and of each member bank and to require such statements and reports as it may deem necessary. The said board shall publish once each week a statement showing the condition of each Federal reserve bank and a consolidated statement for all Federal reserve banks. Such statements shall show in detail the assets and liabilities of the Federal reserve banks, single and combined, and shall furnish full information regarding the character of the money held as reserve and the amount, nature, and maturities of the paper and other investments owned or held by Federal reserve banks."],[0,"(2) To require any depository institution specified in this paragraph to make, at such intervals as the Board may prescribe, such reports of its liabilities and assets as the Board may determine to be necessary or desirable to enable the Board to discharge its responsibility to monitor and control monetary and credit aggregates. Such reports shall be made (A) directly to the Board in the case of member banks and in the case of other depository institutions whose reserve requirements under sections 461, 463, 464, 465, and 466 of this title exceed zero, and (B) for all other reports to the Board through the (i) Federal Deposit Insurance Corporation in the case of insured State savings associations that are insured depository institutions (as defined in section 1813 of this title), State nonmember banks, savings banks, and mutual savings banks, (ii) National Credit Union Administration Board in the case of insured credit unions, (iii) the Comptroller of the Currency in the case of any Federal savings association which is an insured depository institution (as defined in section 1813 of this title) or which is a member as defined in section 1422 of this title, and (iv) such State officer or agency as the Board may designate in the case of any other type of bank, savings association, or credit union. The Board shall endeavor to avoid the imposition of unnecessary burdens on reporting institutions and the duplication of other reporting requirements. Except as otherwise required by law, any data provided to any department, agency, or instrumentality of the United States pursuant to other reporting requirements shall be made available to the Board. The Board may classify depository institutions for the purposes of this paragraph and may impose different requirements on each such class."],[0,"(b) Permitting or requiring rediscounting of paper at specified rate"],[0,"To permit, or, on the affirmative vote of at least five members of the Board of Governors, to require Federal reserve banks to rediscount the discounted paper of other Federal reserve banks at rates of interest to be fixed by the Board."],[0,"(c) Suspending reserve requirements"],[0,"To suspend for a period not exceeding thirty days, and from time to time to renew such suspension for periods not exceeding fifteen days, any reserve requirements specified in this chapter."],[0,"(d) Supervising and regulating issue and retirement of notes"],[0,"To supervise and regulate through the Secretary of the Treasury the issue and retirement of Federal Reserve notes, except for the cancellation and destruction, and accounting with respect to such cancellation and destruction, of notes unfit for circulation, and to prescribe rules and regulations under which such notes may be delivered by the Secretary of the Treasury to the Federal Reserve agents applying therefor."],[0,"(e) Adding to or reclassifying reserve cities"],[0,"To add to the number of cities classified as reserve cities under existing law in which national banking associations are subject to the reserve requirements set forth in section 20 of this Act, or to reclassify existing reserve cities or to terminate their designation as such."],[0,"(f) Suspending or removing officers or directors of reserve banks"],[0,"To suspend or remove any officer or director of any Federal reserve bank, the cause of such removal to be forthwith communicated in writing by the Board of Governors of the Federal Reserve System to the removed officer or director and to said bank."],[0,"(g) Requiring writing off of doubtful or worthless assets of banks"],[0,"To require the writing off of doubtful or worthless assets upon the books and balance sheets of Federal reserve banks."],[0,"(h) Suspending operations of or liquidating or reorganizing banks"],[0,"To suspend, for the violation of any of the provisions of this chapter, the operations of any Federal reserve bank, to take possession thereof, administer the same during the period of suspension, and, when deemed advisable, to liquidate or reorganize such bank."],[0,"(i) Requiring bonds of agents; safeguarding property in hands of agents"],[0,"To require bonds of Federal reserve agents, to make regulations for the safeguarding of all collateral, bonds, Federal reserve notes, money, or property of any kind deposited in the hands of such agents, and said board shall perform the duties, functions, or services specified in this chapter, and make all rules and regulations necessary to enable said board effectively to perform the same."],[0,"(j) Exercising supervision over reserve banks"],[0,"To exercise general supervision over said Federal reserve banks."],[0,"(k) Delegation of certain functions; power to delegate; review of delegated activities"],[0,"To delegate, by published order or rule and subject to subchapter II of chapter 5, and chapter 7, of title 5, any of its functions, other than those relating to rulemaking or pertaining principally to monetary and credit policies, to one or more administrative law judges, members or employees of the Board, or Federal Reserve banks. The assignment of responsibility for the performance of any function that the Board determines to delegate shall be a function of the Chairman. The Board shall, upon the vote of one member, review action taken at a delegated level within such time and in such manner as the Board shall by rule prescribe. The Board of Governors may not delegate to a Federal reserve bank its functions for the establishment of policies for the supervision and regulation of depository institution holding companies and other financial firms supervised by the Board of Governors."],[0,"(l) Employing attorneys, experts, assistants, and clerks; salaries and fees"],[0,"To employ such attorneys, experts, assistants, clerks, or other employees as may be deemed necessary to conduct the business of the board. All salaries and fees shall be fixed in advance by said board and shall be paid in the same manner as the salaries of the members of said board. All such attorneys, experts, assistants, clerks, and other employees shall be appointed without regard to the provisions of the Act of January sixteenth, eighteen hundred and eighty-three (volume twenty-two, United States Statutes at Large, page four hundred and three), and amendments thereto, or any rule or regulation made in pursuance thereof: Provided, That nothing herein shall prevent the President from placing said employees in the classified service."],[0,"(m) [Repealed]"],[0,"(n) Board's authority to examine depository institutions and affiliates"],[0,"To examine, at the Board's discretion, any depository institution, and any affiliate of such depository institution, in connection with any advance to, any discount of any instrument for, or any request for any such advance or discount by, such depository institution under this chapter."],[0,"(o) Authority to appoint conservator or receiver"],[0,"The Board may appoint the Federal Deposit Insurance Corporation as conservator or receiver for a State member bank under section 1821(c)(9) of this title."],[0,"(p) Authority"],[0,"The Board may act in its own name and through its own attorneys in enforcing any provision of this title,1 regulations promulgated hereunder, or any other law or regulation, or in any action, suit, or proceeding to which the Board is a party and which involves the Board's regulation or supervision of any bank, bank holding company (as defined in section 1841 of this title), or other entity, or the administration of its operations."],[0,"(q) Uniform protection authority for Federal reserve facilities"],[0,"(1) Notwithstanding any other provision of law, to authorize personnel to act as law enforcement officers to protect and safeguard the premises, grounds, property, personnel, including members of the Board, of the Board, or any Federal reserve bank, and operations conducted by or on behalf of the Board or a reserve bank."],[0,"(2) The Board may, subject to the regulations prescribed under paragraph (5), delegate authority to a Federal reserve bank to authorize personnel to act as law enforcement officers to protect and safeguard the bank's premises, grounds, property, personnel, and operations conducted by or on behalf of the bank."],[0,"(3) Law enforcement officers designated or authorized by the Board or a reserve bank under paragraph (1) or (2) are authorized while on duty to carry firearms and make arrests without warrants for any offense against the United States committed in their presence, or for any felony cognizable under the laws of the United States committed or being committed within the buildings and grounds of the Board or a reserve bank if they have reasonable grounds to believe that the person to be arrested has committed or is committing such a felony. Such officers shall have access to law enforcement information that may be necessary for the protection of the property or personnel of the Board or a reserve bank."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/248?type=usc&year=mostrecent&link-type=html"},"by":{"0":"36","1":"37","2":"15"}},{"t":"usc","label":"12 U.S.C. § 263","url":"https://www.law.cornell.edu/uscode/text/12/263","by":{"0":"34","1":"38"}},{"t":"usc","label":"12 U.S.C. § 288","url":"https://www.law.cornell.edu/uscode/text/12/288","subs":["(a)(2)"],"by":{"0":"33"}},{"t":"usc","label":"12 U.S.C. § 289","url":"https://www.law.cornell.edu/uscode/text/12/289","subs":["(a)(3)(A)"],"by":{"0":"33"}},{"t":"usc","label":"12 U.S.C. § 341","url":"https://www.law.cornell.edu/uscode/text/12/341","by":{"0":"34","1":"37"}},{"t":"usc","label":"12 U.S.C. § 342","url":"https://www.law.cornell.edu/uscode/text/12/342","by":{"0":"3"}},{"t":"usc","label":"12 U.S.C. § 355","url":"https://www.law.cornell.edu/uscode/text/12/355","by":{"0":"23, 33"}},{"t":"law","label":"Pub. L. No. 106-569","url":"https://www.govinfo.gov/link/plaw/106/public/569","by":{"0":"20"}},{"t":"usc","label":"12 U.S.C. § 2601","url":"https://www.law.cornell.edu/uscode/text/12/2601","by":{"0":"47"}},{"t":"usc","label":"15 U.S.C. § 1601","url":"https://www.law.cornell.edu/uscode/text/15/1601","by":{"0":"47"}},{"t":"usc","label":"15 U.S.C. § 1635","url":"https://www.law.cornell.edu/uscode/text/15/1635","by":{"0":"48"}},{"t":"usc","label":"15 U.S.C. § 1638","url":"https://www.law.cornell.edu/uscode/text/15/1638","by":{"0":"47"}},{"t":"usc","label":"8 U.S.C. § 1356","url":"https://www.law.cornell.edu/uscode/text/8/1356","subs":["(m)","(n)","(d)","(h)(1)(A)","(h)(1)(B)"],"by":{"0":"23, 23, 23","1":"35","2":"17, 17, 17"}},{"t":"usc","label":"12 U.S.C. § 16","url":"https://www.law.cornell.edu/uscode/text/12/16","stext":{"head":"§16. Funding of Office","paras":[[0,"The Comptroller of the Currency may collect an assessment, fee, or other charge from any entity described in section 1813(q)(1) of this title, as the Comptroller determines is necessary or appropriate to carry out the responsibilities of the Office of the Comptroller of the Currency. In establishing the amount of an assessment, fee, or charge collected from an entity under this section, the Comptroller of the Currency may take into account the nature and scope of the activities of the entity, the amount and type of assets that the entity holds, the financial and managerial condition of the entity, and any other factor, as the Comptroller of the Currency determines is appropriate. Funds derived from any assessment, fee, or charge collected or payment made pursuant to this section may be deposited by the Comptroller of the Currency in accordance with the provisions of section 192 of this title. Such funds shall not be construed to be Government funds or appropriated monies, and shall not be subject to apportionment for purposes of chapter 15 of title 31 or any other provision of law. The authority of the Comptroller of the Currency under this section shall be in addition to the authority under subchapter XV of chapter 3."],[0,"The Comptroller of the Currency shall have sole authority to determine the manner in which the obligations of the Office of the Comptroller of the Currency shall be incurred and its disbursements and expenses allowed and paid, in accordance with this section, except as provided in chapter 71 of title 5 (with respect to compensation)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/16?type=usc&year=mostrecent&link-type=html"},"by":{"0":"23, 30, 32, 37","2":"3"},"q":[{"src":"brief","b":0,"text":"determines [are] necessary or appropriate to carry out the responsibilities of the [OCC].","cite":"12 U.S.C. 16"},{"src":"brief","b":0,"text":"as the Comptroller determines is necessary or appropriate to carry out the responsibilities of the Office.","cite":"12 U.S.C. 16"},{"src":"brief","b":2,"text":"determines [are] necessary or appropriate to carry out the responsibilities of the Office,","cite":"12 U.S.C. 16"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"necessary or appropriate to carry out [its] responsibilities.","cite":"12 U. S. C. § 16"}]},{"t":"usc","label":"12 U.S.C. § 192","url":"https://www.law.cornell.edu/uscode/text/12/192","by":{"0":"32"}},{"t":"usc","label":"12 U.S.C. § 481","url":"https://www.law.cornell.edu/uscode/text/12/481","by":{"0":"23, 32, 37"}},{"t":"usc","label":"12 U.S.C. § 482","url":"https://www.law.cornell.edu/uscode/text/12/482","by":{"0":"23"}},{"t":"usc","label":"12 U.S.C. § 4516","url":"https://www.law.cornell.edu/uscode/text/12/4516","by":{"0":"23"}},{"t":"usc","label":"19 U.S.C. § 58c","url":"https://www.law.cornell.edu/uscode/text/19/58c","stext":{"head":"§58c. Fees for certain customs services","paras":[[0,"(a) Schedule of fees"],[0,"In addition to any other fee authorized by law, the Secretary of the Treasury shall charge and collect the following fees (subject to adjustment under subsection (l)) for the provision of customs services in connection with the following:"],[1,"(1) For the arrival of a commercial vessel of 100 net tons or more, $397."],[1,"(2) For the arrival of a commercial truck, $5."],[1,"(3) For the arrival of each railroad car carrying passengers or commercial freight, $7.50."],[1,"(4) For all arrivals made during a calendar year by a private vessel or private aircraft, $25."],[1,"(5)(A) Subject to subparagraph (B), for the arrival of each passenger aboard a commercial vessel or commercial aircraft from a place outside the United States (other than a place referred to in subsection (b)(1)(A)(i) of this section), $5."],[1,"(B) For the arrival of each passenger aboard a commercial vessel from a place referred to in subsection (b)(1)(A)(i) of this section, $1.75."],[1,"(6) For each item of dutiable mail for which a document is prepared by a customs officer (other than an item subject to a fee under subsection (b)(9)(D)), $5."],[1,"(7) For each customs broker permit held by an individual, partnership, association, or corporate customs broker, $125 per year."],[1,"(8) For the arrival of a barge or other bulk carrier from Canada or Mexico, $100."],[1,"(9)(A) For the processing of merchandise that is formally entered or released during any fiscal year, a fee in an amount equal to 0.21 1 percent ad valorem, unless adjusted under subparagraph (B)."],[1,"(B)(i) The Secretary of the Treasury may adjust the ad valorem rate specified in subparagraph (A) to an ad valorem rate (but not to a rate of more than 0.21 1 percent nor less than 0.15 percent) and the amounts specified in subsection (b)(8)(A)(i) (but not to more than $485 nor less than $21) to rates and amounts which would, if charged, offset the salaries and expenses that will likely be incurred by the Customs Service in the processing of such entries and releases during the fiscal year in which such costs are incurred."],[1,"(ii) In determining the amount of any adjustment under clause (i), the Secretary of the Treasury shall take into account whether there is a surplus or deficit in the fund established under subsection (f) with respect to the provision of customs services for the processing of formal entries and releases of merchandise."],[1,"(iii) An adjustment may not be made under clause (i) with respect to the fee charged during any fiscal year unless the Secretary of the Treasury—"],[2,"(I) not later than 45 days after the date of the enactment of the Act providing full-year appropriations for the Customs Service for that fiscal year, publishes in the Federal Register a notice of intent to adjust the fee under this paragraph and the amount of such adjustment;"],[2,"(II) provides a period of not less than 30 days following publication of the notice described in subclause (I) for public comment and consultation with the Committee on Finance of the Senate and the Committee on Ways and Means of the House of Representatives regarding the proposed adjustment and the methodology used to determine such adjustment;"],[2,"(III) upon the expiration of the period provided under subclause (II), notifies such committees in writing regarding the final determination to adjust the fee, the amount of such adjustment, and the methodology used to determine such adjustment; and"],[2,"(IV) upon the expiration of the 15-day period following the written notification described in subclause (III), submits for publication in the Federal Register notice of the final determination regarding the adjustment of the fee."],[1,"(iv) The 15-day period referred to in clause (iii)(IV) shall be computed by excluding—"],[2,"(I) the days on which either House is not in session because of an adjournment of more than 3 days to a day certain or an adjournment of the Congress sine die; and"],[2,"(II) any Saturday and Sunday, not excluded under subclause (I), when either House is not in session."],[1,"(v) An adjustment made under this subparagraph shall become effective with respect to formal entries and releases made on or after the 15th calendar day after the date of publication of the notice described in clause (iii)(IV) and shall remain in effect until adjusted under this subparagraph."],[1,"(C) Any fee charged under this paragraph, whether or not adjusted under subparagraph (B), is subject to the limitations in subsection (b)(8)(A)."],[1,"(10) For the processing of merchandise that is informally entered or released, other than at—"],[2,"(A) a centralized hub facility,"],[2,"(B) an express consignment carrier facility, or"],[2,"(C) a small airport or other facility to which section 58b of this title applies, if more than 25,000 informal entries were cleared through such airport or facility during the fiscal year preceding such entry or release (other than Inbound EMS items described in subsection (b)(9)(D)),"],[1,"a fee of—"],[2,"(i) $2 if the entry or release is automated and not prepared by customs personnel;"],[2,"(ii) $6 if the entry or release is manual and not prepared by customs personnel; or"],[2,"(iii) $9 if the entry or release, whether automated or manual, is prepared by customs personnel."],[1,"For provisions relating to the informal entry or release of merchandise at facilities referred to in subparagraphs (A), (B), and (C), or of Inbound EMS items described in subsection (b)(9)(D), see subsection (b)(9)."],[0,"(b) Limitations on fees"],[0,"(1)(A) Except as provided in subsection (a)(5)(B) of this section, no fee may be charged under subsection (a) of this section for customs services provided in connection with—"],[1,"(i) the arrival of any passenger whose journey—"],[2,"(I) originated in a territory or possession of the United States; or"],[2,"(II) originated in the United States and was limited to territories and possessions of the United States;"],[1,"(ii) the arrival of any railroad car the journey of which originates and terminates in the same country, but only if no passengers board or disembark from the train and no cargo is loaded or unloaded from such car while the car is within any country other than the country in which such car originates and terminates;"],[1,"(iii) the arrival of a ferry, except for a ferry whose operations begin on or after August 1, 1999, and that operates south of 27 degrees latitude and east of 89 degrees longitude; or"],[1,"(iv) the arrival of any passenger on board a commercial vessel traveling only between ports which are within the customs territory of the United States."],[0,"(B) The exemption provided for in subparagraph (A) shall not apply in the case of the arrival of any passenger on board a commercial vessel whose journey originates and terminates at the same place in the United States if there are no intervening stops."],[0,"(C) The exemption provided for in subparagraph (A)(i) shall not apply to fiscal years 1994, 1995, 1996, and 1997."],[0,"(2) No fee may be charged under subsection (a)(2) for the arrival of a commercial truck during any calendar year after a total of $100 in fees (subject to adjustment under subsection (l)) has been paid to the Secretary of the Treasury for the provision of customs services for all arrivals of such commercial truck during such calendar year."],[0,"(3) No fee may be charged under subsection (a)(3) for the arrival of a railroad car whether passenger or freight during any calendar year after a total of $100 in fees (subject to adjustment under subsection (l)) has been paid to the Secretary of the Treasury for the provision of customs services for all arrivals of such passenger or freight rail car during such calendar year."],[0,"(4)(A) No fee may be charged under subsection (a)(5) with respect to the arrival of any passenger—"],[1,"(i) who is in transit to a destination outside the customs territory of the United States, and"],[1,"(ii) for whom customs inspectional services are not provided."],[0,"(B) In the case of a commercial vessel making a single voyage involving 2 or more United States ports with respect to which the passengers would otherwise be charged a fee pursuant to subsection (a)(5), such fee shall be charged only 1 time for each passenger."],[0,"(5) No fee may be charged under subsection (a)(1) for the arrival of—"],[1,"(A) a vessel during a calendar year after a total of $5,955 in fees (subject to adjustment under subsection (l)) charged under paragraph (1) or (8) of subsection (a) has been paid to the Secretary of the Treasury for the provision of customs services for all arrivals of such vessel during such calendar year,"],[1,"(B) any vessel which, at the time of the arrival, is being used solely as a tugboat, or"],[1,"(C) any barge or other bulk carrier from Canada or Mexico."],[0,"(6) No fee may be charged under subsection (a)(8) for the arrival of a barge or other bulk carrier during a calendar year after a total of $1,500 in fees (subject to adjustment under subsection (l)) charged under paragraph (1) or (8) of subsection (a) has been paid to the Secretary of the Treasury for the provision of customs services for all arrivals of such barge or other bulk carrier during such calendar year."],[0,"(7) No fee may be charged under paragraph (2), (3), or (4) of subsection (a) for the arrival of any—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/19/58c?type=usc&year=mostrecent&link-type=html"},"by":{"0":"23, 31","1":"35","2":"17, 17, 17"},"q":[{"src":"brief","b":1,"text":"to the extent provided for in appropriations Acts,","cite":"19 U.S.C. § 58c(f)(2)"}]},{"t":"usc","label":"20 U.S.C. § 54","url":"https://www.law.cornell.edu/uscode/text/20/54","by":{"0":"20"}},{"t":"usc","label":"20 U.S.C. § 1070h","url":"https://www.law.cornell.edu/uscode/text/20/1070h","by":{"0":"21"}},{"t":"usc","label":"21 U.S.C. § 136a","url":"https://www.law.cornell.edu/uscode/text/21/136a","subs":["(a)"],"by":{"0":"24, 31","1":"35"}},{"t":"usc","label":"31 U.S.C. § 1304","url":"https://www.law.cornell.edu/uscode/text/31/1304","subs":["(a)"],"by":{"0":"21","2":"4"}},{"t":"usc","label":"31 U.S.C. § 1305","url":"https://www.law.cornell.edu/uscode/text/31/1305","subs":["(2)"],"by":{"0":"21","2":"4"}},{"t":"usc","label":"31 U.S.C. § 5136","url":"https://www.law.cornell.edu/uscode/text/31/5136","by":{"0":"31"}},{"t":"usc","label":"35 U.S.C. § 41","url":"https://www.law.cornell.edu/uscode/text/35/41","by":{"0":"31"}},{"t":"usc","label":"42 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/42/301","by":{"0":"21","2":"4"}},{"t":"usc","label":"42 U.S.C. § 401","url":"https://www.law.cornell.edu/uscode/text/42/401","subs":["(b)","(a)"],"by":{"0":"21","2":"4, 4"}},{"t":"reg","label":"82 Fed. Reg. 54,472","url":"https://www.govinfo.gov/link/fr/82/54472","by":{"0":"5","1":"7"}},{"t":"reg","label":"84 Fed. Reg. 4252","url":"https://www.govinfo.gov/link/fr/84/4252","by":{"0":"6"}},{"t":"reg","label":"85 Fed. Reg. 41,905","url":"https://www.govinfo.gov/link/fr/85/41905","by":{"0":"6","1":"7"}},{"t":"reg","label":"85 Fed. Reg. 44,382","url":"https://www.govinfo.gov/link/fr/85/44382","by":{"0":"6","1":"7"}},{"t":"case","label":"A. L. A. Schechter Poultry Corp. v. United States","cite":"295 U.S. 495","y":1935,"id":"1900-1940/295us495","sc":1,"by":{"1":"29"}},{"t":"case","label":"Abbott Labs. v. Gardner","cite":"387 U.S. 136","y":1967,"id":"1966/39","sc":1,"by":{"1":"50–51"}},{"t":"case","label":"Financial Oversight & Mgmt. Bd. for P.R. v. Aurelius Inv., LLC","cite":"140 S. Ct. 1649","y":2020,"id":"2019/18-1334","sc":1,"by":{"1":"6, 42"}},{"t":"case","label":"Gundy v. United States","cite":"139 S. Ct. 2116","y":2019,"id":"2018/17-6086","sc":1,"by":{"1":"28–30"},"q":[{"src":"argument","who":"Mr. Francisco","text":"And, here, it's delegated that judgment to the director in a way, I think, that the Gundy dissent illustrates the problems with this type of regime."}]},{"t":"case","label":"Health & Hosp. Corp. of Marion Cnty. v. Talevski","cite":"2023 WL 3872515","y":2023,"court":"U.S. June 8","by":{"1":"48"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"by":{"1":"20, 29"}},{"t":"case","label":"Kramer v. Union Free Sch. Dist. No. 15","cite":"395 U.S. 621","y":1969,"id":"1968/258","sc":1,"by":{"1":"43"},"q":[{"src":"brief","b":1,"text":"the deference usually given to the judgment of legislators.","cite":"395 U.S. 621, 627-28"}]},{"t":"case","label":"Lucia v. SEC","cite":"138 S. Ct. 2044","y":2018,"id":"2017/17-130","sc":1,"by":{"1":"47–48, 50","2":"22"},"q":[{"src":"brief","b":1,"text":"designed … to create incentives to raise … challenges.","cite":"138 S. Ct. at 2055 n.5"},{"src":"brief","b":2,"text":"create incentives to raise . . . challenges.","cite":"138 S. Ct. 2044, 2055 n.5"}]},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"by":{"1":"28–29"},"q":[{"src":"brief","b":1,"text":"related to the exercise of executive … powers.","cite":"488 U.S. 361, 420"}]},{"t":"case","label":"Morrison v. Olson","cite":"487 U.S. 654","y":1988,"id":"1987/87-1279","sc":1,"by":{"1":"24"}},{"t":"case","label":"N. Pipeline Constr. Co. v. Marathon Pipe Line Co.","cite":"458 U.S. 50","y":1982,"id":"1981/81-150","sc":1,"by":{"1":"51"},"q":[{"src":"argument","who":"Mr. Francisco","text":"And if you need to stay your judgment for a period of time, as you did in the Northern Pipeline case, to facilitate that, we certainly have no objection to that."}]},{"t":"case","label":"Nat’l Fed’n of Indep. Bus. v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"by":{"1":"43"}},{"t":"case","label":"Nixon v. Fitzgerald","cite":"457 U.S. 731","y":1982,"id":"1981/79-1738","sc":1,"by":{"1":"21"}},{"t":"case","label":"Randall v. Sorrell","cite":"548 U.S. 230","y":2006,"id":"2005/04-1528","sc":1,"by":{"1":"44–45"},"q":[{"src":"brief","b":1,"text":"require[d] … to foresee which of many different possible ways the legislature might respond to the constitutional objections,","cite":"548 U.S. at 262"}]},{"t":"case","label":"Ryder v. United States","cite":"515 U.S. 177","y":1995,"id":"1994/94-431","sc":1,"by":{"1":"49–51","2":"22, 23"}},{"t":"case","label":"United States v. Gentile","cite":"2017 WL 1437532","y":2017,"court":"E.D. Cal. Apr. 24","by":{"1":"49"}},{"t":"case","label":"United States v. Richardson","cite":"418 U.S. 166","y":1974,"id":"1973/72-885","sc":1,"by":{"1":"15"},"q":[{"src":"brief","b":1,"text":"[t]he ultimate weapon … available to the Congress","cite":"418 U.S. 166, 178 n.11"}]},{"t":"case","label":"Va. Office for Prot. & Advoc. v. Stewart","cite":"563 U.S. 247","y":2011,"id":"2010/09-529","sc":1,"by":{"1":"49"},"q":[{"src":"brief","b":1,"text":"The fact that the Federal Government can exercise oversight of … federal spending … []does not demonstrate that Congress has displayed an intent","cite":"563 U.S. 247, 256 n.3"},{"src":"argument","who":"General Prelogar","text":"The first Congress did exactly this with the very first agency it created, the Customs Service, and the same is true for other founding-era agencies, including the Post Office, the National Mint, the Patent Office, revenue officers, and the National Bank."},{"src":"argument","who":"Justice Sotomayor","text":"-- it for -- does it use it for the Post Office and for the Mint and for other agencies of that nature?"},{"src":"argument","who":"General Prelogar","text":"So, Justice Sotomayor, I'm not familiar with whether this particular language appears in the statutes governing the Post Office. You know, the Post Office, of course, was originally created and funded in -- in 1792, and so it's not clear that some of these other background rules existed, but, certainly, we can point to examples today, including the OCC and the FCA, which have this same language, and I think it's meant to ensure, again, that there's no disruption with the funding operating in the way that Congress intended."}]},{"t":"case","label":"Webster v. Doe","cite":"486 U.S. 592","y":1988,"id":"1987/86-1294","sc":1,"by":{"1":"29"},"q":[{"src":"brief","b":1,"text":"foreclose[s] the application of any meaningful judicial standard of review,","cite":"486 U.S. 592, 600"}]},{"t":"case","label":"Whitman v. Am. Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"by":{"1":"27–31, 39","2":"10"},"q":[{"src":"brief","b":1,"text":"var[y] according to the scope of the power congressionally conferred.","cite":"531 U.S. at 475"},{"src":"brief","b":2,"text":"‘necessary to avoid an imminent hazard.’","cite":"531 U.S. 457, 473"}]},{"t":"const","label":"Article I, Section 8, Clause 12","text":"To raise and support Armies, but no Appropriation of Money to that Use shall be for a longer Term than two Years;","by":{"1":"21"}},{"t":"const","label":"Article I, Section 9, Clause 7","clauses":[["appropriations","Appropriations Clause"]],"text":"No Money shall be drawn from the Treasury, but in Consequence of Appropriations made by Law; and a regular Statement and Account of the Receipts and Expenditures of all public Money shall be published from time to time.","by":{"1":"1, 9, 11, 16, 25"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","by":{"1":"3, 10, 47–48"}},{"t":"usc","label":"12 U.S.C. § 248a","url":"https://www.law.cornell.edu/uscode/text/12/248a","by":{"1":"37"}},{"t":"usc","label":"12 U.S.C. § 321","url":"https://www.law.cornell.edu/uscode/text/12/321","by":{"1":"37"}},{"t":"usc","label":"12 U.S.C. § 328","url":"https://www.law.cornell.edu/uscode/text/12/328","by":{"1":"37"}},{"t":"usc","label":"12 U.S.C. § 371b","url":"https://www.law.cornell.edu/uscode/text/12/371b","by":{"1":"38"}},{"t":"usc","label":"28 U.S.C. § 2401","url":"https://www.law.cornell.edu/uscode/text/28/2401","by":{"1":"51"}},{"t":"usc","label":"35 U.S.C. § 42","url":"https://www.law.cornell.edu/uscode/text/35/42","by":{"1":"35"}},{"t":"law","label":"Dodd-Frank Wall Street Reform and Consumer Protection Act, Pub. L. No. 111-203","url":"https://www.govinfo.gov/link/plaw/111/public/203","by":{"1":"4"}},{"t":"reg","label":"12 C.F.R. § 1041.7","url":"https://www.ecfr.gov/current/title-12/section-1041.7","by":{"1":"7"}},{"t":"reg","label":"12 C.F.R. § 1041.8","url":"https://www.ecfr.gov/current/title-12/section-1041.8","by":{"1":"7"}},{"t":"case","label":"Haaland v. Brackeen","cite":"143 S. Ct. 1609","y":2023,"id":"2022/21-376","sc":1,"by":{"2":"19"},"q":[{"src":"brief","b":2,"text":"bear the burden of establishing [Section 5497’s] unconstitutionality.","cite":"143 S. Ct. at 1630"}]},{"t":"case","label":"Herring v. United States","cite":"555 U.S. 135","y":2009,"id":"2008/07-513","sc":1,"by":{"2":"22"}},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"580 U.S. 288","y":2017,"url":"https://supreme.justia.com/cases/federal/us/580/288/","sc":1,"by":{"2":"5"},"q":[{"src":"brief","b":2,"text":"why floor statements by individual legislators rank among the least illuminating forms of legislative history.","cite":"580 U.S. 288, 307"}]},{"t":"case","label":"Salazar v. Ramah Navajo Chapter","cite":"567 U.S. 182","y":2012,"id":"2011/11-551","sc":1,"by":{"2":"21"}},{"t":"const","label":"Article I, Section 7, Clause 1","clauses":[["origination","Origination Clause"]],"text":"All Bills for raising Revenue shall originate in the House of Representatives; but the Senate may propose or concur with Amendments as on other Bills.","by":{"2":"13"}},{"t":"usc","label":"15 U.S.C. § 9021","url":"https://www.law.cornell.edu/uscode/text/15/9021","subs":["(g)(1)(B)"],"by":{"2":"4"}},{"t":"usc","label":"15 U.S.C. § 9023","url":"https://www.law.cornell.edu/uscode/text/15/9023","subs":["(d)(3)"],"by":{"2":"4"}},{"t":"usc","label":"19 U.S.C. § 58b","url":"https://www.law.cornell.edu/uscode/text/19/58b","subs":["(e)"],"by":{"2":"17"}}]};